#!/usr/bin/env python3
"""Remove JavaScript from an HTML file, in place.

Usage: python3 filter.py <file.html>

The file is rewritten byte-for-byte identical to the input except for the
removal of the substrings that can execute script:

  * <script> elements (including their content)
  * on* event handler attributes
  * javascript:/vbscript:/... URLs (and script-bearing data: URLs)
  * <meta http-equiv=refresh> pointing at a script URL
  * script constructs inside style sheets / style attributes
  * script inside iframe srcdoc (filtered recursively)

Everything else -- whitespace, indentation, comments, tables, headings,
attribute quoting style, entities -- is preserved exactly.
"""

import html as _html
import re
import sys
from html.parser import HTMLParser

# --------------------------------------------------------------------------
# URL / value inspection
# --------------------------------------------------------------------------

_STRIP_RE = re.compile(r"[\s\x00-\x20\x7f   ]+")

_SCRIPT_SCHEMES = (
    "javascript:",
    "vbscript:",
    "livescript:",
    "jscript:",
    "mocha:",
    "data:text/html",
    "data:text/xml",
    "data:application/xhtml",
    "data:application/xml",
    "data:image/svg+xml",
)

# Elements for which *any* data: URL is treated as executable content.
_DATA_URL_SINKS = frozenset(
    ("iframe", "frame", "object", "embed", "a", "link", "base", "form", "applet")
)

# Attributes that hold URLs.
_URL_ATTRS = frozenset(
    (
        "href",
        "src",
        "action",
        "formaction",
        "data",
        "poster",
        "background",
        "cite",
        "longdesc",
        "profile",
        "manifest",
        "codebase",
        "archive",
        "classid",
        "usemap",
        "ping",
        "lowsrc",
        "dynsrc",
        "folder",
        "xlink:href",
        "xml:base",
        "srcset",
        "imagesrcset",
    )
)

# SVG/SMIL animation elements can inject values into other attributes.
_ANIMATION_TAGS = frozenset(
    ("animate", "set", "animatetransform", "animatemotion", "animatecolor")
)
_ANIMATION_ATTRS = frozenset(("to", "from", "values", "by", "attributename"))

# Elements removed together with their content.
_SCRIPT_ELEMENTS = frozenset(("script",))

# Elements whose content is plain text in the browser: pass through untouched.
_RCDATA_ELEMENTS = frozenset(("textarea", "title"))


def _decode(value):
    """Aggressively decode an attribute value for inspection purposes."""
    out = value
    for _ in range(3):
        new = _html.unescape(out)
        if new == out:
            break
        out = new
    return out


def _normalize_url(value):
    return _STRIP_RE.sub("", _decode(value)).lower()


def _is_script_url(value, tag=""):
    norm = _normalize_url(value)
    if norm.startswith(_SCRIPT_SCHEMES):
        return True
    if tag in _DATA_URL_SINKS and norm.startswith("data:"):
        return True
    return False


def _srcset_is_dangerous(value, tag=""):
    for candidate in value.split(","):
        url = candidate.strip().split()[0] if candidate.strip() else ""
        if url and _is_script_url(url, tag):
            return True
    return False


# --------------------------------------------------------------------------
# CSS sanitising
# --------------------------------------------------------------------------

_CSS_DANGER_RE = re.compile(
    r"""(?ix)
    (?: expression \s* \(
      | behaviou?r \s* :
      | -moz-binding
      | (?: javascript | vbscript | livescript | mocha ) \s* :
      | @ \s* import
      | url \s* \( \s* ['"]? \s*
          (?: javascript | vbscript | livescript | data \s* : \s* text \s* / \s* html ) \s* :?
    )
    """
)

_CSS_DECL_RE = re.compile(r"[^;{}]*")


def _sanitize_css(css):
    """Drop declarations/at-rules that can execute script, keep the rest."""
    decoded = _decode(css)
    if not _CSS_DANGER_RE.search(_STRIP_RE.sub("", decoded)) and not _CSS_DANGER_RE.search(
        decoded
    ):
        return css

    out = []
    pos = 0
    length = len(css)
    while pos < length:
        match = _CSS_DECL_RE.match(css, pos)
        chunk = match.group(0)
        end = match.end()
        terminator = css[end : end + 1]
        candidate = chunk + terminator
        probe = _decode(chunk)
        if _CSS_DANGER_RE.search(probe) or _CSS_DANGER_RE.search(_STRIP_RE.sub("", probe)):
            # Drop the whole declaration, keep the structural terminator.
            out.append(terminator if terminator in "{}" else "")
        else:
            out.append(candidate)
        pos = end + (1 if terminator else 0)
        if not terminator and end == pos - 0 and match.end() == match.start():
            pos += 1
    return "".join(out)


# --------------------------------------------------------------------------
# Raw start-tag surgery
# --------------------------------------------------------------------------

_SPACE = " \t\n\r\f\v"


class _RawAttr(object):
    __slots__ = ("ws_start", "start", "end", "name", "value", "val_start", "val_end", "quote")

    def __init__(self, ws_start, start, end, name, value, val_start, val_end, quote):
        self.ws_start = ws_start
        self.start = start
        self.end = end
        self.name = name
        self.value = value
        self.val_start = val_start
        self.val_end = val_end
        self.quote = quote


def _scan_tag(raw):
    """Split a raw start tag into (name_end, [attrs], tail_start)."""
    length = len(raw)
    i = 1
    while i < length and raw[i] not in _SPACE + "/>":
        i += 1
    name_end = i
    attrs = []
    while i < length:
        ws_start = i
        while i < length and (raw[i] in _SPACE or raw[i] == "/"):
            i += 1
        if i >= length or raw[i] == ">":
            i = ws_start
            break
        start = i
        while i < length and raw[i] not in _SPACE + "/>=":
            i += 1
        name = raw[start:i]
        after_name = i
        j = i
        while j < length and raw[j] in _SPACE:
            j += 1
        value = None
        val_start = val_end = -1
        quote = ""
        if j < length and raw[j] == "=":
            j += 1
            while j < length and raw[j] in _SPACE:
                j += 1
            if j < length and raw[j] in "\"'":
                quote = raw[j]
                close = raw.find(quote, j + 1)
                if close == -1:
                    close = length
                val_start = j + 1
                val_end = close
                value = raw[val_start:val_end]
                i = min(close + 1, length)
            else:
                val_start = j
                while j < length and raw[j] not in _SPACE + ">":
                    j += 1
                val_end = j
                value = raw[val_start:val_end]
                i = j
        else:
            i = after_name
        attrs.append(_RawAttr(ws_start, start, i, name, value, val_start, val_end, quote))
    return name_end, attrs, i


def _escape_attr(value, quote):
    out = value.replace("&", "&amp;")
    if quote == "'":
        return out.replace("'", "&#39;")
    return out.replace("\"", "&quot;")


def _rewrite_tag(raw, tag):
    """Return the sanitised raw text of a start tag (unchanged if clean)."""
    name_end, attrs, tail_start = _scan_tag(raw)
    changed = False
    pieces = [raw[:name_end]]

    meta_refresh = tag == "meta" and any(
        a.name.lower() == "http-equiv"
        and a.value is not None
        and _decode(a.value).strip().lower() == "refresh"
        for a in attrs
    )

    for attr in attrs:
        lname = attr.name.lower()
        raw_value = attr.value if attr.value is not None else ""
        decoded = _decode(raw_value)
        drop = False
        new_value = None

        if lname.startswith("on") and len(lname) > 2:
            drop = True
        elif lname in ("style",) and attr.value is not None:
            cleaned = _sanitize_css(raw_value)
            if cleaned != raw_value:
                new_value = cleaned
        elif lname == "srcdoc" and attr.value is not None:
            cleaned = filter_html(decoded)
            if cleaned != decoded:
                new_value = _escape_attr(cleaned, attr.quote or '"')
        elif lname in ("srcset", "imagesrcset"):
            if _srcset_is_dangerous(decoded, tag):
                drop = True
        elif lname in _URL_ATTRS or lname.endswith(":href"):
            if _is_script_url(decoded, tag):
                drop = True
        elif meta_refresh and lname == "content":
            stripped = _STRIP_RE.sub("", _decode(decoded)).lower()
            if any(scheme in stripped for scheme in _SCRIPT_SCHEMES):
                drop = True
        elif tag in _ANIMATION_TAGS and lname in _ANIMATION_ATTRS:
            if _is_script_url(decoded, tag) or _normalize_url(decoded).startswith("on"):
                drop = True

        if drop:
            changed = True
            continue
        if new_value is not None:
            changed = True
            if attr.quote:
                pieces.append(raw[attr.ws_start : attr.val_start])
                pieces.append(new_value)
                pieces.append(raw[attr.val_end : attr.end])
            else:
                pieces.append(
                    raw[attr.ws_start : attr.start]
                    + attr.name
                    + '="'
                    + _escape_attr(new_value, '"')
                    + '"'
                )
            continue
        pieces.append(raw[attr.ws_start : attr.end])

    pieces.append(raw[tail_start:])
    if not changed:
        return raw
    return "".join(pieces)


# --------------------------------------------------------------------------
# Document scanning
# --------------------------------------------------------------------------


class _Scanner(HTMLParser):
    """Collect every construct of the document with its source offset."""

    def __init__(self, text):
        try:
            HTMLParser.__init__(self, convert_charrefs=False)
        except TypeError:  # very old Python
            HTMLParser.__init__(self)
        self._text = text
        self._line_starts = [0]
        for idx, char in enumerate(text):
            if char == "\n":
                self._line_starts.append(idx + 1)
        self.events = []

    def _offset(self):
        line, col = self.getpos()
        if line - 1 < len(self._line_starts):
            return min(self._line_starts[line - 1] + col, len(self._text))
        return len(self._text)

    def _add(self, kind, payload=None):
        self.events.append([self._offset(), kind, payload])

    # -- handlers ---------------------------------------------------------
    def handle_starttag(self, tag, attrs):
        self._add("start", tag)

    def handle_startendtag(self, tag, attrs):
        self._add("startend", tag)

    def handle_endtag(self, tag):
        self._add("end", tag)

    def handle_data(self, data):
        self._add("data")

    def handle_entityref(self, name):
        self._add("data")

    def handle_charref(self, name):
        self._add("data")

    def handle_comment(self, data):
        self._add("comment")

    def handle_decl(self, decl):
        self._add("decl")

    def handle_pi(self, data):
        self._add("pi")

    def unknown_decl(self, data):
        self._add("decl")


def filter_html(text):
    """Return *text* with every script-executing construct removed."""
    if not text:
        return text

    scanner = _Scanner(text)
    try:
        scanner.feed(text)
        scanner.close()
    except Exception:
        pass
    events = [e for e in scanner.events]
    events.sort(key=lambda e: e[0])

    out = []
    if events:
        out.append(text[: events[0][0]])
    else:
        return text

    suppress_depth = 0  # inside a <script> element
    rcdata_stack = []

    for index, (start, kind, payload) in enumerate(events):
        end = events[index + 1][0] if index + 1 < len(events) else len(text)
        raw = text[start:end]
        if not raw:
            continue

        if suppress_depth:
            if kind == "start" and payload in _SCRIPT_ELEMENTS:
                suppress_depth += 1
            elif kind == "end" and payload in _SCRIPT_ELEMENTS:
                suppress_depth -= 1
            continue

        if rcdata_stack:
            if kind == "end" and payload == rcdata_stack[-1]:
                rcdata_stack.pop()
            out.append(raw)
            continue

        if kind in ("start", "startend"):
            if payload in _SCRIPT_ELEMENTS:
                if kind == "start" and not raw.rstrip().endswith("/>"):
                    suppress_depth = 1
                continue
            if kind == "start" and payload in _RCDATA_ELEMENTS:
                rcdata_stack.append(payload)
            out.append(_rewrite_tag(raw, payload))
            continue

        if kind == "end":
            if payload in _SCRIPT_ELEMENTS:
                continue
            out.append(raw)
            continue

        if kind == "data":
            out.append(raw)
            continue

        out.append(raw)

    return "".join(out)


def _style_pass(text):
    """Sanitise the content of <style> elements (their text is CSS)."""
    pattern = re.compile(r"(?is)(<style\b[^>]*>)(.*?)(</style\s*>|\Z)")

    def repl(match):
        return match.group(1) + _sanitize_css(match.group(2)) + match.group(3)

    return pattern.sub(repl, text)


def sanitize(text):
    return _style_pass(filter_html(text))


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: filter.py <html-file>\n")
        return 2
    path = argv[1]
    with open(path, "rb") as handle:
        data = handle.read()

    encoding = "utf-8"
    try:
        text = data.decode(encoding)
        errors = "strict"
    except UnicodeDecodeError:
        text = data.decode(encoding, "surrogateescape")
        errors = "surrogateescape"

    cleaned = sanitize(text)

    with open(path, "wb") as handle:
        handle.write(cleaned.encode(encoding, errors))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

